<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/config.php';require_once BASE_PATH.'/shared/auth.php';require_once BASE_PATH.'/shared/database.php';require_once BASE_PATH.'/shared/cost-workbook.php';require_once BASE_PATH.'/shared/openai-extractor.php';require_once BASE_PATH.'/shared/pdf-extractor.php';require_role('owner_admin');header('Content-Type: application/json; charset=utf-8');
function tc_reply(array $v,int $s=200):void{http_response_code($s);echo json_encode($v,JSON_UNESCAPED_SLASHES);exit;}function tc_body():array{$v=json_decode((string)file_get_contents('php://input'),true);return is_array($v)?$v:[];}function tc_date($v):?string{$v=trim((string)$v);$d=DateTimeImmutable::createFromFormat('Y-m-d',$v);return$d&&$d->format('Y-m-d')===$v?$v:null;}function tc_num($v):float{return max(0,(float)str_replace([',','N$'],'',(string)$v));}function tc_money($v):string{return number_format((float)$v,2,'.','');}function tc_user():array{return cw_user();}
function tc_invoice_weight(array $row):array{$kg=(float)($row['weight_kg']??0);if($kg>0)return[$kg,(string)($row['weight_status']??'estimated')];$base=(float)($row['weight_base']??0);return$base>0?[$base,'actual']:[0,'missing'];}
try{$pdo=db();cw_install_schema($pdo);$action=(string)($_GET['action']??'list');if(in_array($action,['save','upload','archive'],true)&&$_SERVER['REQUEST_METHOD']!=='POST')tc_reply(['ok'=>false,'error'=>'Use POST for this action.'],405);if($_SERVER['REQUEST_METHOD']!=='GET')cw_require_csrf();
if($action==='list'){$where=[];$params=[];$basis=($_GET['date_basis']??'transport')==='upload'?'DATE(t.uploaded_at)':'t.transport_date';foreach(['from'=>'>=','to'=>'<='] as $k=>$op){$v=tc_date($_GET[$k]??'');if($v){$where[]="$basis$op?";$params[]=$v;}}foreach(['source'=>'t.entry_source','method'=>'t.allocation_method','status'=>'t.allocation_status'] as $k=>$c){$v=trim((string)($_GET[$k]??''));if($v!==''){$where[]="$c=?";$params[]=$v;}}$courier=trim((string)($_GET['courier']??''));if($courier!==''){$where[]='t.courier_name LIKE ?';$params[]='%'.$courier.'%';}$q=trim((string)($_GET['q']??''));if($q!==''){$where[]='(t.courier_name LIKE ? OR t.invoice_number LIKE ? OR t.waybill_references LIKE ? OR t.notes LIKE ? OR EXISTS(SELECT 1 FROM cw_transport_allocations ax JOIN cw_supplier_invoices ix ON ix.id=ax.supplier_invoice_id WHERE ax.transport_id=t.id AND (ix.supplier_name LIKE ? OR ix.invoice_number LIKE ?)))';$l='%'.substr($q,0,100).'%';array_push($params,$l,$l,$l,$l,$l,$l);}if(($_GET['status']??'')!=='archived')$where[]="t.allocation_status<>'archived'";$sqlWhere=$where?' WHERE '.implode(' AND ',$where):'';$sql="SELECT t.*,COALESCE(SUM(a.calculated_amount),0) allocated,COUNT(a.id) linked_count,GROUP_CONCAT(DISTINCT i.supplier_name ORDER BY i.supplier_name SEPARATOR ', ') suppliers FROM cw_transport_records t LEFT JOIN cw_transport_allocations a ON a.transport_id=t.id LEFT JOIN cw_supplier_invoices i ON i.id=a.supplier_invoice_id{$sqlWhere} GROUP BY t.id ORDER BY COALESCE(t.transport_date,DATE(t.uploaded_at)) DESC,t.id DESC";$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();$records=count($rows);$full=0;$needs=0;$unallocated=0;foreach($rows as &$r){$allocated=(float)$r['allocated']+cw_packaging_freight_claimed($pdo,(int)$r['id']);$available=(float)$r['allocable_amount'];$remaining=max(0,$available-$allocated);$r['unallocated']=tc_money($remaining);$r['allocated']=tc_money($allocated);$weight=(float)($r['actual_weight_kg']?:$r['estimated_weight_kg']);$r['weight_kg']=$weight;$r['weight_status']=$r['actual_weight_kg']?'actual':($r['estimated_weight_kg']?'estimated':'missing');$r['rate_per_kg']=$weight>0?tc_money($allocated/$weight):null;if($remaining<.005)$full++;else{$needs++;$unallocated+=$remaining;}}unset($r);tc_reply(['rows'=>$rows,'summary'=>['records'=>$records,'allocated'=>$full,'needs'=>$needs,'unallocated'=>tc_money($unallocated)]]);}
if($action==='candidates'){$st=$pdo->query("SELECT i.id,i.supplier_name,i.invoice_number,i.invoice_date,i.currency,i.invoice_total,COALESCE(SUM(CASE WHEN l.base_unit='kg' THEN l.base_quantity ELSE 0 END),0) weight_base,COALESCE(SUM(CASE WHEN l.base_unit='L' THEN l.base_quantity ELSE 0 END),0) litres FROM cw_supplier_invoices i LEFT JOIN cw_supplier_invoice_lines l ON l.supplier_invoice_id=i.id WHERE i.approval_status<>'archived' GROUP BY i.id ORDER BY i.invoice_date DESC,i.id DESC LIMIT 300");tc_reply(['rows'=>$st->fetchAll()]);}
if($action==='detail'){$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT * FROM cw_transport_records WHERE id=?');$st->execute([$id]);$record=$st->fetch();if(!$record)tc_reply(['error'=>'Transport record not found.'],404);$st=$pdo->prepare('SELECT a.*,i.supplier_name,i.invoice_number,i.invoice_date FROM cw_transport_allocations a JOIN cw_supplier_invoices i ON i.id=a.supplier_invoice_id WHERE a.transport_id=? ORDER BY a.id');$st->execute([$id]);tc_reply(['record'=>$record,'allocations'=>$st->fetchAll(),'original_url'=>$record['stored_file']?'transport-costs-api.php?action=file&id='.$id:null]);}
if($action==='upload'){if(empty($_FILES['transport_file'])||!is_uploaded_file((string)$_FILES['transport_file']['tmp_name']))throw new RuntimeException('Select a transport invoice file.');$f=$_FILES['transport_file'];if((int)$f['error']!==UPLOAD_ERR_OK||(int)$f['size']<=0||(int)$f['size']>15*1024*1024)throw new RuntimeException('Transport invoice files must be 15 MB or smaller.');$ext=strtolower(pathinfo((string)$f['name'],PATHINFO_EXTENSION));$allowed=['pdf'=>'application/pdf','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png'];if(!isset($allowed[$ext]))throw new RuntimeException('Upload a supported PDF, JPG, JPEG or PNG transport invoice.');$mime=(string)(new finfo(FILEINFO_MIME_TYPE))->file((string)$f['tmp_name']);if($mime!==$allowed[$ext])throw new RuntimeException('The file content does not match its extension.');$hash=hash_file('sha256',(string)$f['tmp_name']);$st=$pdo->prepare("SELECT id FROM cw_transport_records WHERE file_hash=? AND allocation_status<>'archived'");$st->execute([$hash]);if($dup=(int)$st->fetchColumn())tc_reply(['error'=>'Possible duplicate transport invoice.','duplicate_id'=>$dup],409);$dir=BASE_PATH.'/uploads/cost-workbook/transport/'.date('Y/m');if(!is_dir($dir)&&!mkdir($dir,0750,true)&&!is_dir($dir))throw new RuntimeException('Secure upload storage is unavailable.');$stored=date('YmdHis').'-'.bin2hex(random_bytes(8)).'.'.$ext;$relative='uploads/cost-workbook/transport/'.date('Y/m').'/'.$stored;if(!move_uploaded_file((string)$f['tmp_name'],$dir.'/'.$stored))throw new RuntimeException('The transport invoice could not be stored.');$u=tc_user();$pdo->prepare("INSERT INTO cw_transport_records(entry_source,original_filename,stored_file,file_type,file_hash,extraction_status,extraction_message,created_by,created_by_name) VALUES('uploaded',?,?,?,?, 'manual_review','Automatic extraction unavailable. Confirm transport details manually.',?,?)")->execute([basename((string)$f['name']),$relative,$mime,$hash,$u['id'],$u['name']]);tc_reply(['ok'=>true,'id'=>(int)$pdo->lastInsertId(),'message'=>'Automatic extraction unavailable — please confirm the transport details manually.']);}
if($action==='save'){cw_require_admin();tc_reply(cw_transport_save($pdo,tc_body()));}
if($action==='archive'){$b=tc_body();$id=(int)($b['id']??0);if(cw_packaging_freight_claimed($pdo,$id)>0)throw new DomainException('This transport has packaging allocations. Correct those references before archiving.');$pdo->prepare("UPDATE cw_transport_records SET allocation_status='archived' WHERE id=?")->execute([$id]);tc_reply(['ok'=>true]);}
if($action==='file'){$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT original_filename,stored_file,file_type FROM cw_transport_records WHERE id=?');$st->execute([$id]);$f=$st->fetch();$path=$f?BASE_PATH.'/'.$f['stored_file']:'';if(!$f||!is_file($path))throw new RuntimeException('Original transport invoice is unavailable.');header_remove('Content-Type');header('Content-Type: '.$f['file_type']);header('Content-Disposition: inline; filename="'.rawurlencode((string)$f['original_filename']).'"');header('X-Content-Type-Options: nosniff');readfile($path);exit;}tc_reply(['error'=>'Unknown action.'],404);
}catch(Throwable $e){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();tc_reply(['error'=>$e->getMessage()],400);}
